import json
import random
from dataclasses import dataclass
from datetime import date, timedelta
from pathlib import Path
from typing import Any, Callable, Dict, Iterable, List, Optional, Sequence

from fluxsense.samples import embed_zugferd
from fluxsense.testdata import ids, vocab
from fluxsense.testdata.documents import (LogicalDoc, build_enclosure, build_form, build_invoice, build_letter,
                                          build_private_note, build_receipt, build_stack, build_statement,
                                          build_telecom_invoice, build_transfer)
from fluxsense.testdata.layout import render
from fluxsense.testdata.scan import make_scan

BUILDERS: Dict[str, Callable[[random.Random], List[LogicalDoc]]] = {
    "invoice": lambda rng: [build_invoice(rng)],
    "invoice_long": lambda rng: [build_invoice(rng, long=True)],
    "invoice_bilingual": lambda rng: [build_invoice(rng, long=True, bilingual=True)],
    "invoice_zugferd": lambda rng: [build_invoice(rng, zugferd=True)],
    "telecom_invoice": lambda rng: [build_telecom_invoice(rng, totals_page=rng.choice((1, 2)))],
    "bank_statement": lambda rng: [build_statement(rng)],
    "card_statement": lambda rng: [build_statement(rng, card=True)],
    "letter": lambda rng: [build_letter(rng)],
    "official_letter": lambda rng: [build_letter(rng, official=True)],
    "form": lambda rng: [build_form(rng)],
    "receipt": lambda rng: [build_receipt(rng)],
    "transfer": lambda rng: [build_transfer(rng)],
    "enclosure": lambda rng: [build_enclosure(rng)],
    "note": lambda rng: [build_private_note(rng)],
    "stack": build_stack,
}
KINDS: Sequence[str] = ("invoice", "invoice_long", "invoice_bilingual", "invoice_zugferd", "telecom_invoice", "bank_statement",
                        "card_statement", "letter", "official_letter", "form", "receipt", "transfer", "note", "stack")
SMOKE_SEED = 1


@dataclass
class GeneratedFile:
    """One generated PDF with its logical documents and ground-truth entry."""

    path: Path
    kind: str
    scan: bool
    docs: List[LogicalDoc]
    entry: Dict[str, Any]
    manifest: Dict[str, Any]


def rng_for(seed: int, index: int, purpose: str) -> random.Random:
    """The random source of one file and purpose (stable across Python versions and hash seeds)."""
    return random.Random(f"fluxsense-testdata/{seed}/{index}/{purpose}")


def truth_entry(file_id: str, name: str, docs: Sequence[LogicalDoc], seed: int) -> Dict[str, Any]:
    """Ground-truth entry of one file (evaluator format)."""
    logical: List[Dict[str, Any]] = []
    first = 1
    for doc in docs:
        record: Dict[str, Any] = {"pages": list(range(first, first + len(doc.pages))), "doc_types": list(doc.doc_types)}
        record.update(json.loads(json.dumps(doc.truth)))
        record["visual"] = dict(doc.visual)
        record["language"] = doc.language
        record["summary"] = doc.summary
        logical.append(record)
        first += len(doc.pages)
    return {"id": file_id, "path": name, "logical_documents": logical, "uncertain_fields": [],
            "notes": f"generated by fluxsense gen-testdocs (seed {seed}); exact by construction"}


def generate_file(directory: Path, seed: int, index: int, kind: str, scan: Optional[bool] = None,
                  scan_share: float = 0.25) -> GeneratedFile:
    """
    Builds, renders and records one file.

    Args:
        directory: Output directory.
        seed: Set seed.
        index: File index within the set.
        kind: Key of BUILDERS.
        scan: Force (True) or forbid (False) the scan variant; None: random by scan_share.
        scan_share: Probability of a scan variant.

    Returns:
        GeneratedFile.
    """
    docs = BUILDERS[kind](rng_for(seed, index, kind))
    variant = rng_for(seed, index, "variant")
    is_scan = (variant.random() < scan_share) if scan is None else scan
    if kind == "invoice_zugferd":
        is_scan = False if scan is None else scan
    name = f"gen{seed}_{index + 1:03d}_{kind}{'_scan' if is_scan else ''}.pdf"
    path = directory / name
    pages = [page for doc in docs for page in doc.pages]
    digital = directory / f".{name}.digital.pdf" if is_scan else path
    render(pages, digital, title=docs[0].summary, subject=kind)
    xml = next((doc.xml for doc in docs if doc.xml), None)
    if xml:
        embedded = digital.with_name(f".{name}.xml.pdf")
        embed_zugferd(digital, embedded, xml)
        embedded.replace(digital)
    if is_scan:
        stamp_text = None
        if docs[0].kind == "invoice" and variant.random() < 0.6:
            paid = date.fromisoformat(docs[0].truth["doc_date"]) + timedelta(days=variant.randint(3, 20))
            stamp_text = f"BEZAHLT {ids.fmt_date_de(paid)}"
            docs[0].visual["has_stamp"] = True
        handwritten = variant.random() < 0.3
        docs[0].visual["has_handwriting"] = docs[0].visual["has_handwriting"] or handwritten
        make_scan(digital, path, variant, stamp_text, handwritten)
        digital.unlink()
    entry = truth_entry(f"gen{seed}-{index + 1:03d}", name, docs, seed)
    chars = 0 if is_scan else sum(len(doc.text()) for doc in docs)
    manifest = {"id": entry["id"], "path": name, "pages": len(pages), "chars": chars, "kind": "scan" if is_scan else "digital",
                "embedded": ["factur-x.xml"] if xml else []}
    return GeneratedFile(path, kind, is_scan, docs, entry, manifest)


def generate_set(out: Path, seed: int, count: int, scan_share: float = 0.25,
                 kinds: Optional[Sequence[str]] = None) -> List[GeneratedFile]:
    """
    Writes a test-document set: PDFs, ground_truth.json and manifest.json.

    Args:
        out: Output directory (created).
        seed: Seed; the same seed always yields the same documents and truth.
        count: Number of files (kinds are cycled).
        scan_share: Share of scan variants.
        kinds: Kinds to cycle (default: KINDS).

    Returns:
        The generated files.
    """
    out.mkdir(parents=True, exist_ok=True)
    order = list(kinds or KINDS)
    unknown = [k for k in order if k not in BUILDERS]
    if unknown:
        raise ValueError(f"unknown document kinds: {', '.join(unknown)}")
    files = [generate_file(out, seed, index, order[index % len(order)], scan_share=scan_share) for index in range(count)]
    (out / "ground_truth.json").write_text(json.dumps([f.entry for f in files], indent=1, ensure_ascii=False), encoding="utf-8")
    (out / "manifest.json").write_text(json.dumps([f.manifest for f in files], indent=1), encoding="utf-8")
    return files


def smoke_set(out: Path) -> List[GeneratedFile]:
    """The public smoke benchmark: every kind twice (seed 1), a quarter of the files as scans."""
    return generate_set(out, SMOKE_SEED, 2 * len(KINDS))


def vocabulary() -> List[str]:
    """Every built-in word / name entry of the generator (for the privacy denylist check)."""
    entries: List[str] = []
    for name in dir(vocab):
        value = getattr(vocab, name)
        if name.isupper():
            entries.extend(_flatten(value))
    return entries


def _flatten(value: Any) -> Iterable[str]:
    if isinstance(value, str):
        yield value
    elif isinstance(value, dict):
        for key, item in value.items():
            yield from _flatten(key)
            yield from _flatten(item)
    elif isinstance(value, (tuple, list)):
        for item in value:
            yield from _flatten(item)


def denylist_hits(texts: Iterable[str], denylist: Iterable[str]) -> List[str]:
    """
    Denylist entries found in texts (case-insensitive, whitespace-normalised).

    Args:
        texts: Generator vocabulary or generated document texts.
        denylist: Entries that must never occur (names, numbers, phrases).

    Returns:
        The denylist entries that occur.
    """
    haystack = "\n".join(" ".join(t.lower().split()) for t in texts)
    compact = "".join(haystack.split())
    hits = []
    for entry in denylist:
        needle = " ".join(entry.lower().split())
        if needle and (needle in haystack or (len(needle) >= 8 and "".join(needle.split()) in compact)):
            hits.append(entry)
    return hits
